SET @p := (SELECT menu_id FROM sys_menu WHERE parent_id=0 AND path='future' LIMIT 1); INSERT INTO sys_menu(menu_name,parent_id,order_num,path,component,route_name,is_frame,is_cache,menu_type,visible,status,perms,icon,create_by,create_time,update_by,update_time,remark) SELECT '期货交易日与时段',@p,13,'calendar','future/calendar','FutureCalendar',1,0,'C','0','0','future:history:list','calendar','admin',NOW(),'admin',NOW(),'t_future_trading_calendar' WHERE NOT EXISTS(SELECT 1 FROM sys_menu WHERE parent_id=@p AND path='calendar'); INSERT INTO sys_role_menu(role_id,menu_id) SELECT 1,menu_id FROM sys_menu WHERE parent_id=@p AND path='calendar' AND NOT EXISTS(SELECT 1 FROM sys_role_menu x WHERE x.role_id=1 AND x.menu_id=sys_menu.menu_id);
